}

/* 去掉body的背景，让容器直接显示 */
body {
    font-family: -apple-system, BlinkMacSystemFont, "PingFang SC", "Microsoft YaHei", sans-serif;
    /* 不设置背景色，保持透明 */
}

/* 主容器 - 固定尺寸，无外部背景 */
.phone-container {
    width: 280px;
    height: 600px;
    border: 1px solid #ddd;
    border-radius: 30px;
