<script>
let currentPage = 1;
const totalPages = 9;

let characterData = {
    name: '',
    age: '',
    appearance: '',
    background: '',
    race: '',
    raceBonus: '',
    faction: '',
    equipment: '',
    items: '',
    misc: '',
    assets: '',
    skills: '',
    startStory: '',
    attributes: {
        yi: 0,
        qi: 0,
        agi: 0,
        ac: 0
    },
    remainingPoints: 20
};

function updateProgress() {
    const progress = (currentPage / totalPages) * 100;
    document.getElementById('progress').style.width = progress + '%';
}

function nextPage() {
    // 验证当前页面数据
    if (currentPage === 5 && !characterData.race) {
        alert('请选择种族！');
        return;
    }

    if (currentPage === 6 && !characterData.faction && !document.getElementById('customFaction').value) {
        alert('请选择势力！');
        return;
    }

    if (currentPage === 8) {
        // 保存所有自定义信息
        characterData.name = document.getElementById('charName').value;
        characterData.age = document.getElementById('charAge').value;
        characterData.appearance = document.getElementById('charAppearance').value;
        characterData.background = document.getElementById('charBackground').value;
        characterData.equipment = document.getElementById('charEquipment').value;
        characterData.items = document.getElementById('charItems').value;
        characterData.misc = document.getElementById('charMisc').value;
        characterData.assets = document.getElementById('charAssets').value;
        characterData.skills = document.getElementById('charSkills').value;
        characterData.startStory = document.getElementById('charStartStory').value;

        if (!characterData.name || !characterData.age) {
            alert('请填写姓名和年龄！');
            return;
        }

        updateSummary();
    }

    // 切换页面
    document.getElementById('page' + currentPage).classList.remove('active');
    currentPage++;
    document.getElementById('page' + currentPage).classList.add('active');
    updateProgress();
}

function prevPage() {
    document.getElementById('page' + currentPage).classList.remove('active');
    currentPage--;
    document.getElementById('page' + currentPage).classList.add('active');
    updateProgress();
}

function selectRace(race, bonus) {
    characterData.race = race;
    characterData.raceBonus = bonus;

    document.querySelectorAll('.race-card').forEach(card => {
        card.classList.remove('selected');
    });
    event.target.closest('.race-card').classList.add('selected');
}

function selectFaction(faction) {
    characterData.faction = faction;
    document.getElementById('customFaction').value = '';

    document.querySelectorAll('.faction-card').forEach(card => {
        card.classList.remove('selected');
    });
    event.target.closest('.faction-card').classList.add('selected');
}

function increaseAttr(attr) {
    if (characterData.remainingPoints > 0) {
        characterData.attributes[attr]++;
        characterData.remainingPoints--;
        updateAttrDisplay();
    }
}

function decreaseAttr(attr) {
    if (characterData.attributes[attr] > 0) {
        characterData.attributes[attr]--;
        characterData.remainingPoints++;
        updateAttrDisplay();
    }
}

function updateAttrDisplay() {
    document.getElementById('yi-value').textContent = characterData.attributes.yi;
    document.getElementById('qi-value').textContent = characterData.attributes.qi;
    document.getElementById('agi-value').textContent = characterData.attributes.agi;
    document.getElementById('ac-value').textContent = characterData.attributes.ac;
    document.getElementById('remainingPoints').textContent = characterData.remainingPoints;
}

function updateSummary() {
    document.getElementById('summary-name').textContent = characterData.name;
    document.getElementById('summary-age').textContent = characterData.age;
    document.getElementById('summary-race').textContent = characterData.race;

    // 处理自定义势力
    const customFaction = document.getElementById('customFaction').value;
    document.getElementById('summary-faction').textContent = customFaction || characterData.faction;

    document.getElementById('summary-yi').textContent = characterData.attributes.yi;
    document.getElementById('summary-qi').textContent = characterData.attributes.qi;
    document.getElementById('summary-agi').textContent = characterData.attributes.agi;
    document.getElementById('summary-ac').textContent = characterData.attributes.ac;
}

// 修改createCharacter函数，添加开局故事
function createCharacter() {
    const customFaction = document.getElementById('customFaction').value;
    const finalFaction = customFaction || characterData.faction;

    // 生成角色数据 - 添加开局故事
    const output = `<名字>${characterData.name}</名字>
<年龄>${characterData.age}</年龄>
<等级>武徒</等级>
<身份势力>${finalFaction}</身份势力>
<种族>${characterData.race}</种族>
<外貌>${characterData.appearance}</外貌>
<背景故事>${characterData.background}</背景故事>
<装备>${characterData.equipment}</装备>
<道具>${characterData.items}</道具>
<杂物>${characterData.misc}</杂物>
<资产>${characterData.assets}</资产>
<生命值>60/60</生命值>
<经验值>0/25</经验值>
