<script>
// 页面切换
function showPage(pageNum) {
    // 隐藏所有页面
    const pages = document.querySelectorAll('.page');
    pages.forEach(page => page.classList.remove('active'));

    // 隐藏所有导航按钮的active状态
    const navBtns = document.querySelectorAll('.nav-btn');
    navBtns.forEach(btn => btn.classList.remove('active'));

    // 显示选中的页面
    document.getElementById('page-' + pageNum).classList.add('active');
    document.getElementById('nav-' + pageNum).classList.add('active');
}

// 标签页切换
function showTab(tabName) {
    // 隐藏所有标签内容
    const tabs = document.querySelectorAll('.tab-content');
    tabs.forEach(tab => tab.classList.remove('active'));

    // 隐藏所有标签按钮的active状态
    const tabBtns = document.querySelectorAll('.tab-btn');
    tabBtns.forEach(btn => btn.classList.remove('active'));

    // 显示选中的标签
    document.getElementById('tab-content-' + tabName).classList.add('active');
    document.getElementById('tab-' + tabName).classList.add('active');

    // 如果是属性标签，绘制雷达图
    if (tabName === 'attrs') {
        drawRadarChart();
    }
}

// 区域详情切换
function toggleZone(zoneName) {
    const zoneElement = document.getElementById('zone-' + zoneName);
    const allZones = document.querySelectorAll('.zone-details');

    // 如果当前区域已经显示，则隐藏
    if (zoneElement.classList.contains('active')) {
        zoneElement.classList.remove('active');
    } else {
        // 隐藏所有区域
        allZones.forEach(zone => zone.classList.remove('active'));
        // 显示选中的区域
        zoneElement.classList.add('active');
    }
}

// 属性系统相关变量和函数
let attrPoints = parseInt('$20') || 0;
const originalAttrs = {
    yi: parseInt('$21') || 10,
    qi: parseInt('$22') || 10,
    agi: parseInt('$23') || 10,
    ac: parseInt('$24') || 10
};

let currentAttrs = {...originalAttrs};
let attrChanges = {yi: 0, qi: 0, agi: 0, ac: 0};

function increaseAttr(attr) {
    if (attrPoints > 0) {
        currentAttrs[attr]++;
        attrChanges[attr]++;
        attrPoints--;
        updateAttrDisplay();
    }
}

function decreaseAttr(attr) {
    if (attrChanges[attr] > 0) {
        currentAttrs[attr]--;
        attrChanges[attr]--;
        attrPoints++;
        updateAttrDisplay();
    }
}

function updateAttrDisplay() {
    document.getElementById('attr-points').textContent = attrPoints;
    document.getElementById('attr-yi').textContent = currentAttrs.yi;
    document.getElementById('attr-qi').textContent = currentAttrs.qi;
    document.getElementById('attr-agi').textContent = currentAttrs.agi;
    document.getElementById('attr-ac').textContent = currentAttrs.ac;

    // 更新指令文本
    let command = '';
    const attrNames = {yi: '意', qi: '气', agi: '敏捷', ac: 'AC'};
    for (let attr in attrChanges) {
        if (attrChanges[attr] > 0) {
            command += `${attrNames[attr]}+${attrChanges[attr]} `;
        }
    }
    document.getElementById('attr-command').value = command.trim();

    // 更新按钮状态
    updateButtonStates();

    // 更新雷达图
    drawRadarChart();
}

function updateButtonStates() {
    // 禁用/启用加号按钮
    document.querySelectorAll('.attr-btn').forEach(btn => {
        if (btn.textContent === '+') {
            btn.disabled = attrPoints <= 0;
        }
    });

    // 禁用/启用减号按钮
    ['yi', 'qi', 'agi', 'ac'].forEach(attr => {
        const minusBtn = document.querySelector(`[onclick="decreaseAttr('${attr}')"]`);
        if (minusBtn) {
            minusBtn.disabled = attrChanges[attr] <= 0;
        }
    });
}

function resetAttrs() {
    currentAttrs = {...originalAttrs};
    attrPoints = parseInt('$20') || 0;
    attrChanges = {yi: 0, qi: 0, agi: 0, ac: 0};
    updateAttrDisplay();
}

function copyAttrCommand() {
    const command = document.getElementById('attr-command');
    command.select();
    document.execCommand('copy');

    // 显示复制成功提示
    const buttons = document.querySelectorAll('.cmd-btn');
    buttons.forEach(btn => {
        if (btn.textContent === '复制指令' || btn.textContent === '已复制!') {
            const originalText = '复制指令';
            btn.textContent = '已复制!';
            setTimeout(() => {
                btn.textContent = originalText;
            }, 1000);
        }
    });
}

// 绘制雷达图
function drawRadarChart() {
    const canvas = document.getElementById('radarChart');
    if (!canvas) return;

    const ctx = canvas.getContext('2d');
    const centerX = canvas.width / 2;
    const centerY = canvas.height / 2;
    const radius = 100;

    // 清空画布
    ctx.clearRect(0, 0, canvas.width, canvas.height);

    // 属性标签和值
    const labels = ['意', '气', '敏捷', 'AC'];
    const values = [
        currentAttrs.yi,
        currentAttrs.qi,
        currentAttrs.agi,
        currentAttrs.ac
    ];

    // 计算最大值
    const maxValue = Math.max(...values, 30);

    // 绘制网格
    ctx.strokeStyle = 'rgba(212, 175, 55, 0.3)';
    ctx.lineWidth = 1;

    for (let i = 1; i <= 5; i++) {
        ctx.beginPath();
        for (let j = 0; j < 4; j++) {
            const angle = (Math.PI * 2 / 4) * j - Math.PI / 2;
            const x = centerX + Math.cos(angle) * (radius * i / 5);
            const y = centerY + Math.sin(angle) * (radius * i / 5);

            if (j === 0) {
                ctx.moveTo(x, y);
            } else {
                ctx.lineTo(x, y);
            }
        }
        ctx.closePath();
        ctx.stroke();
    }

    // 绘制轴线
    for (let i = 0; i < 4; i++) {
        const angle = (Math.PI * 2 / 4) * i - Math.PI / 2;
        ctx.beginPath();
        ctx.moveTo(centerX, centerY);
        ctx.lineTo(
            centerX + Math.cos(angle) * radius,
            centerY + Math.sin(angle) * radius
        );
        ctx.stroke();
    }

    // 绘制数据区域
    ctx.fillStyle = 'rgba(212, 175, 55, 0.3)';
    ctx.strokeStyle = '#d4af37';
    ctx.lineWidth = 2;

    ctx.beginPath();
    for (let i = 0; i < 4; i++) {
        const angle = (Math.PI * 2 / 4) * i - Math.PI / 2;
        const value = values[i] / maxValue;
        const x = centerX + Math.cos(angle) * (radius * value);
        const y = centerY + Math.sin(angle) * (radius * value);

        if (i === 0) {
            ctx.moveTo(x, y);
        } else {
            ctx.lineTo(x, y);
        }
    }
    ctx.closePath();
    ctx.fill();
    ctx.stroke();

    // 绘制标签
    ctx.fillStyle = '#d4af37';
    ctx.font = 'bold 14px Arial';
    ctx.textAlign = 'center';
    ctx.textBaseline = 'middle';

    for (let i = 0; i < 4; i++) {
        const angle = (Math.PI * 2 / 4) * i - Math.PI / 2;
                const labelX = centerX + Math.cos(angle) * (radius + 25);
        const labelY = centerY + Math.sin(angle) * (radius + 25);

        ctx.fillText(labels[i] + ': ' + values[i], labelX, labelY);
    }
}

// 初始化
document.addEventListener('DOMContentLoaded', function() {
    // 初始化属性显示
    updateAttrDisplay();

    // 确保第一个页面显示
    showPage(1);
});
</script>

</body>
</html>
